function flattenTopics(subjectId) {
  let n = 0;
  return subjects[subjectId].sections.flatMap((section, sectionIndex) => section.topics.map((t) => {
    const title = Array.isArray(t) ? t[0] : t;
    const generated = subjectId === 'reading'
      ? [`Мәтінді мұқият оқып, тақырыпқа қатысты негізгі ойды, автор ұстанымын және мәтін ішіндегі дәлелдерді анықта. Бейтаныс сөзді контекст бойынша түсіндір.`, ['Негізгі ой мен нақты ақпаратты табу', 'Мәтін құрылымы мен стильдік ерекшелікті ажырату', 'Қорытынды мен автор көзқарасын мәтінге сүйеніп анықтау']]
      : subjectId === 'mathlit'
        ? [`Өмірлік жағдаяттың шартын қысқаша жазып, қажет деректерді бөліп ал. Сәйкес амал не формуланы таңдап, нәтижені жуық бағамен тексер.`, ['Шарттан қажетті деректерді іріктеу', 'Тиісті өрнек, формула немесе кестені қолдану', 'Жауаптың өлшем бірлігі мен қисындылығын тексеру']]
        : [`Оқиғаларды уақыт ретімен орналастырып, себеп-салдар мен тарихи маңызын байланыстыр. Тұлға, дерек және карта бойынша мәліметті салыстыр.`, ['Негізгі дата, тұлға және оқиға байланысын қайталау', 'Себеп-салдар мен тарихи нәтижені түсіндіру', 'Дерек, карта немесе схема бойынша қорытынды жасау']];
    return {
      id: `${subjectId}-${String(++n).padStart(2, '0')}`,
      title, summary: Array.isArray(t) ? t[1] : generated[0], goals: Array.isArray(t) ? t[2] : generated[1], section: section.title, sectionIndex, number: String(n).padStart(2, '0')
    };
  }));
}
