function save() { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }
function esc(value) { return String(value).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
function localDateKey(date = new Date()) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; }
function weekKey(date = new Date()) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  const week = Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
  return `${d.getUTCFullYear()}-${String(week).padStart(2, '0')}`;
}
function touchStudyday() {
  const key = localDateKey();
  state.studyDays = [...new Set([...(state.studyDays || []), key])].slice(-90);
}
function calcStreak() {
  const days = new Set(state.studyDays || []);
  const cursor = new Date();
  if (!days.has(localDateKey(cursor))) cursor.setDate(cursor.getDate() - 1);
  let streak = 0;
  while (days.has(localDateKey(cursor)) && streak < 365) { streak++; cursor.setDate(cursor.getDate() - 1); }
  return streak;
}
function topicCount(subjectId) { return subjects[subjectId].topics.filter((t) => state.doneTopics.includes(t.id)).length; }
function totalTopicCount() { return Object.values(subjects).reduce((n, s) => n + s.topics.length, 0); }
function showToast(message) {
  toastNode.textContent = message;
  toastNode.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toastNode.classList.remove('show'), 2400);
}
function setView(next) {
  view = next;
  if (view !== 'subjects') selectedTopicId = null;
  document.querySelectorAll('[data-view]').forEach((button) => button.classList.toggle('active', button.dataset.view === view));
  document.getElementById('crumb-current').textContent = viewNames[view] || 'Оқу кеңістігі';
  document.getElementById('sidebar').classList.remove('open');
  render();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}
function render() {
  clearInterval(quizClock);
  if (view === 'home') main.innerHTML = renderHome();
  if (view === 'subjects') main.innerHTML = renderSubjects();
  if (view === 'videos') main.innerHTML = renderVideos();
  if (view === 'plan') main.innerHTML = renderPlan();
  if (view === 'quiz') main.innerHTML = renderQuiz();
  if (view === 'progress') main.innerHTML = renderProgress();
  if (view === 'review') main.innerHTML = renderReview();
  if (view === 'quiz' && quizRun && !quizRun.finished) {
    quizClock = setInterval(() => {
      const timer = document.getElementById('quiz-elapsed');
      if (timer) timer.textContent = formatElapsed(Date.now() - quizRun.startedAt);
    }, 1000);
  }
}

function formatElapsed(ms) {
  const seconds = Math.max(0, Math.floor(ms / 1000));
  return `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`;
}

function renderHome() {
  const streak = calcStreak();
  const todayKey = localDateKey();
  const daily = state.dailyTasks[todayKey] || [];
  const dailyTasks = [
    { id: 'reading', label: 'Мәтіннен негізгі ойды тап', meta: 'Оқу сауаттылығы · 2 сұрақ', time: '10 мин' },
    { id: 'mathlit', label: 'Бір логикалық есеп шығар', meta: 'Математикалық сауаттылық', time: '10 мин' },
    { id: 'history', label: '5 тарихи датаны еске түсір', meta: 'Қазақстан тарихы · белсенді қайталау', time: '10 мин' },
    { id: 'profile', label: 'Бейіндік пәннен бір тақырып оқы', meta: 'Биология немесе химия', time: '10 мин' },
    { id: 'quiz', label: 'Қысқа тестпен бекіт', meta: 'Күндік мақсат · таңдауыңа қарай', time: '5 мин' }
  ];
  const weekDays = ['Жс', 'Дс', 'Сс', 'Ср', 'Бс', 'Жм', 'Сб'];
  const dots = Array.from({ length: 7 }, (_, i) => {
    const d = new Date(); d.setDate(d.getDate() - (6 - i));
    const key = localDateKey(d); const today = key === todayKey;
    return `<span class="day-dot ${state.studyDays.includes(key) ? 'done' : ''} ${today ? 'today' : ''}"><i>${state.studyDays.includes(key) ? '✓' : '·'}</i>${weekDays[d.getDay()]}</span>`;
  }).join('');
  const nextSubjectId = [...SUBJECT_ORDER].sort((a, b) => topicCount(a) / subjects[a].topics.length - topicCount(b) / subjects[b].topics.length)[0];
  const activeSubject = subjects[nextSubjectId];
  const activeTopic = activeSubject.topics.find((t) => !state.doneTopics.includes(t.id)) || activeSubject.topics[0];
  const doneToday = daily.filter((id) => dailyTasks.some((t) => t.id === id)).length;
  return `
    <div class="page-heading">
      <div><p class="eyebrow"><i class="eyebrow-dot"></i>ОҚУ КЕҢІСТІГІ</p><h1>Бүгінгі қадамың дайын.</h1><p class="subheading">Бес пәнді өз қарқыныңмен меңгер. Аз уақыттың өзін тұрақты бөлсең, тақырыптар біртіндеп орнығады.</p></div>
    </div>
    <div class="dashboard-top">
      <section class="hero-card">
        <span class="hero-kicker"><i></i>5 ПӘН · БІР ЖОСПАР</span>
        <h2>Бір қадамнан үлкен нәтиже.</h2>
        <p>Өзіңді өзгемен емес, кешегі өзіңмен салыстыр. Бүгін бір бөлімді үйреніп, шағын тестпен біліміңді бекіт.</p>
        <button class="btn" data-action="continue" data-subject="${nextSubjectId}">Оқуды жалғастыру <span class="arrow">→</span></button>
        <div class="molecule" aria-hidden="true"><span class="mol-line" style="left:35px;top:58px;width:65px;transform:rotate(29deg)"></span><span class="mol-line" style="left:47px;top:68px;width:57px;transform:rotate(-48deg)"></span><span class="mol-line" style="left:84px;top:84px;width:47px;transform:rotate(14deg)"></span><i class="mol-node big" style="left:18px;top:44px"></i><i class="mol-node" style="left:72px;top:73px"></i><i class="mol-node big" style="left:105px;top:17px"></i><i class="mol-node" style="left:121px;top:90px"></i></div><div class="hero-glow"></div>
      </section>
      <section class="streak-card">
        <div class="streak-head"><span class="small-label">ОҚУ ЫРҒАҒЫ</span><span class="streak-icon">✳</span></div>
        <div><div class="streak-number">${streak}<span> күн қатарынан</span></div><p class="streak-copy">Бүгінгі шағын қадамыңды аяқта. Үзілістен кейін де қайта бастауға болады.</p></div>
        <div class="week-dots">${dots}</div>
      </section>
    </div>

    <section class="dashboard-section">
      <div class="section-heading"><div><h2>Бүгінгі жоспар</h2><p>${doneToday}/${dailyTasks.length} қадам аяқталды · асықпай орында</p></div><button class="inline-link" data-view="plan">Жоспарды ашу <span class="arrow">→</span></button></div>
      <div class="today-layout">
        <div class="task-card">${dailyTasks.map((task) => `<div class="task-row"><button class="task-check ${daily.includes(task.id) ? 'checked' : ''}" data-action="daily-task" data-id="${task.id}" aria-label="${daily.includes(task.id) ? 'Аяқталды' : 'Орындадым деп белгіле'}">✓</button><div class="task-info"><strong>${task.label}</strong><span>${task.meta}</span></div><span class="task-time">${task.time}</span></div>`).join('')}</div>
        <div class="focus-card"><div class="focus-art"><span>✳</span></div><div class="focus-content"><span class="small-label">КЕЛЕСІ ТАҚЫРЫП</span><h3>${activeTopic.title}</h3><p>${activeSubject.name} · ${activeTopic.number}-тақырып</p><button class="btn btn-quiet" data-action="open-topic" data-subject="${nextSubjectId}" data-id="${activeTopic.id}">Тақырыпты оқу <span class="arrow">→</span></button></div></div>
      </div>
    </section>

    <section class="dashboard-section">
      <div class="section-heading"><div><h2>Бейіндік пәндер</h2><p>Ресми спецификацияға сай тақырыптар картасы</p></div><button class="inline-link" data-view="subjects">Барлық тақырып <span class="arrow">→</span></button></div>
      <div class="subject-grid">${SUBJECT_ORDER.map((id) => renderSubjectCard(id)).join('')}</div>
    </section>
    <section class="dashboard-section"><div class="section-heading"><div><h2>Келесі пайдалы қадам</h2><p>Апталық қорытынды жасап, қай пәнге көбірек уақыт бөлетініңді анықта.</p></div></div><div style="display:flex;gap:9px;flex-wrap:wrap"><button class="btn btn-light" data-view="progress">Прогресті көру <span class="arrow">→</span></button><button class="btn btn-light" data-view="videos">Қазақша видеосабақтар <span class="arrow">→</span></button><button class="btn btn-light" data-action="show-format">ҰБТ форматы <span class="arrow">→</span></button></div></section>
  `;
}

function renderSubjectCard(id) {
  const s = subjects[id]; const done = topicCount(id); const count = s.topics.length; const percent = Math.round(done / count * 100);
  return `<article class="subject-card ${s.tone}"><div class="subject-top"><span class="subject-symbol">${s.symbol}</span><span class="small-label">${s.required ? 'МІНДЕТТІ ПӘН' : 'БЕЙІНДІК ПӘН'}</span></div><h3>${s.name}</h3><p class="subject-meta">${s.sections.length} бөлім · ${count} тақырып</p><div class="subject-progress-label"><span>Тақырып ілгерілеуі</span><span>${percent}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${percent}%"></div></div><div class="subject-card-actions"><span class="topic-status">${done}/${count} тақырып белгіленді</span><button class="subject-open" data-action="open-subject" data-subject="${id}">Ашу <span class="arrow">→</span></button></div></article>`;
}

function renderSubjects() {
  const s = subjects[activeSubject];
  const done = topicCount(activeSubject); const percent = Math.round(done / s.topics.length * 100);
  const search = subjectSearch.trim().toLocaleLowerCase('kk');
  let matchCount = 0;
  const sections = s.sections.map((section, sectionIndex) => {
    const topics = s.topics.filter((t) => t.sectionIndex === sectionIndex && (!search || `${t.title} ${t.summary}`.toLocaleLowerCase('kk').includes(search)));
    if (topics.length === 0) return '';
    matchCount += topics.length;
    const isOpen = expandedSections[activeSubject].has(sectionIndex) || !!search;
    return `<section class="topic-section ${isOpen ? 'open' : ''}"><button class="topic-section-header" data-action="toggle-section" data-index="${sectionIndex}"><span class="section-index">${String(sectionIndex + 1).padStart(2, '0')}</span><span class="section-header-copy"><strong>${section.title}</strong><small>${topics.length} тақырып · ${topics.filter((t) => state.doneTopics.includes(t.id)).length} белгіленген</small></span><span class="section-chevron">⌄</span></button><div class="topic-items">${topics.map((topic) => `<div class="topic-row"><span class="topic-index">${topic.number}</span><button class="topic-open" data-action="select-topic" data-id="${topic.id}">${topic.title}</button><button class="topic-done ${state.doneTopics.includes(topic.id) ? 'done' : ''}" data-action="toggle-topic" data-id="${topic.id}" aria-label="${state.doneTopics.includes(topic.id) ? 'Орындалған белгіні алып тастау' : 'Тақырыпты аяқталды деп белгіле'}">✓</button></div>`).join('')}</div></section>`;
  }).join('');
  const selected = selectedTopicId ? s.topics.find((t) => t.id === selectedTopicId) : null;
  const selectedDetail = selected ? `<div class="topic-detail-panel"><span class="detail-number">${s.name} · ${selected.number}-тақырып</span><h3>${selected.title}</h3><p>${selected.summary}</p><ul class="detail-goals">${selected.goals.map((g) => `<li>${g}</li>`).join('')}</ul>${state.doneTopics.includes(selected.id) ? '<span class="done-note">✓ Оқу барысына белгіленді</span>' : `<button class="btn btn-quiet" data-action="toggle-topic" data-id="${selected.id}">Оқып шықтым <span class="arrow">→</span></button>`}</div>` : '';
  return `<div class="page-heading"><div><p class="eyebrow"><i class="eyebrow-dot"></i>ПӘНДЕР КАРТАСЫ</p><h1>Тақырыптарды ретімен меңгер.</h1><p class="subheading">Үш міндетті және екі бейіндік пәннің бөлімдерін аш. Қысқа бағыттамаларды оқып, меңгерген тақырыпты белгілеп отыр.</p></div><label class="search-field"><span class="search-icon">⌕</span><input id="topic-search" type="search" placeholder="Тақырыпты іздеу" value="${esc(subjectSearch)}" aria-label="Тақырыптарды іздеу"></label></div>
    <div class="content-grid"><div class="panel panel-pad ${s.tone}-page"><div class="subject-switcher">${SUBJECT_ORDER.map((id) => { const option = subjects[id]; const activeClass = activeSubject === id ? `active ${option.tone}-tab` : ''; return `<button class="subject-tab ${activeClass}" data-action="choose-subject" data-subject="${id}">${option.name} <span>· ${option.topics.length}</span></button>`; }).join('')}</div>
      <div class="subject-banner ${s.tone}-banner"><div><h2>${s.name} · ${s.questionCount} тапсырмаға дайындық</h2><p>${s.required ? 'Міндетті пән' : 'Бейіндік пән'} · ҰТО спецификациясы бойынша · ${s.maxScore} баллға дейін</p></div><span class="banner-mark">${s.symbol}</span></div>
      <div class="topic-list" id="topics-list">${sections || '<div class="no-results">Іздеу бойынша тақырып табылмады.</div>'}</div>${selectedDetail}
    </div><aside><div class="panel topic-side-card"><span class="side-card-mark">✳</span><h3>Өз қарқыныңды бақыла</h3><p>Тақырыпты оқып шыққанда ✓ белгісін қой. Белгіленген бөлімдер жеке оқу көрсеткішіңе қосылады.</p><div class="side-stat"><span>Меңгерілген тақырып</span><strong>${done}/${s.topics.length}</strong></div><div class="progress-track" style="margin-top:9px"><div class="progress-fill" style="width:${percent}%"></div></div><div class="side-stat"><span>Ілгерілеу</span><strong>${percent}%</strong></div></div><div class="panel topic-side-card" style="margin-top:12px"><span class="side-card-mark">⌕</span><h3>Ресми материалға сүйен</h3><p>Тақырыптар Ұлттық тестілеу орталығының спецификациясымен сәйкестендірілген. Толық тізімді ресми құжаттан қара.</p><p class="source-note"><a href="${SPEC_URLS[activeSubject]}" target="_blank" rel="noreferrer">${s.name}: ресми спецификация ↗</a></p></div></aside></div>`;
}

const weeklyPlan = [
  ['Дүйсенбі', 'Оқу сауаттылығы · мәтінмен жұмыс', 'Негізгі ойды табу + 5 сұрақ'],
  ['Сейсенбі', 'Математикалық сауаттылық · логика', 'Пайыз немесе кесте есебі'],
  ['Сәрсенбі', 'Қазақстан тарихы · бір кезең', 'Даталарды уақыт сызығына түсіру'],
  ['Бейсенбі', 'Биология · бір бөлім', 'Қысқа сабақ + тақырыптық тест'],
  ['Жұма', 'Химия · теория және есеп', 'Формула + бірнеше есеп'],
  ['Сенбі', '5 пән · қысқаша диагностика', 'Аралас 24 тапсырмалық байқау'],
  ['Жексенбі', 'Қате сұрақтар мен видео сабақтар', 'Қиын тақырыпты қайталау']
];
function renderPlan() {
  const key = weekKey(); const done = state.planDone[key] || [];
  return `<div class="page-heading"><div><p class="eyebrow"><i class="eyebrow-dot"></i>ЖҮЙЕЛІ ДАЙЫНДЫҚ</p><h1>Өзіңе ыңғайлы оқу ырғағы.</h1><p class="subheading">Апталық жоспар — ұсынылатын үлгі. Күніне бөлетін уақытыңды таңда, орындаған қадамыңды белгіле. Үзіліс жасауға да болады.</p></div><button class="btn btn-light heading-action" data-action="show-format">ҰБТ құрылымы <span class="arrow">↗</span></button></div>
    <div class="plan-layout"><section class="panel plan-card"><div class="plan-toolbar"><h2>Осы аптаға үлгі жоспар</h2><span class="week-label">${done.length}/7 қадам</span></div><div class="week-plan">${weeklyPlan.map((day, i) => `<div class="plan-day ${done.includes(i) ? 'complete' : ''}"><span class="plan-dayname">${day[0]}</span><span class="plan-task">${day[1]}<small>${day[2]}</small></span><span class="plan-minute">${state.minutes} мин</span><button class="task-check ${done.includes(i) ? 'checked' : ''}" data-action="plan-day" data-index="${i}" aria-label="${done.includes(i) ? 'Орындалды' : 'Белгіле'}">✓</button></div>`).join('')}</div><div class="week-progress"><div class="week-progress-head"><span>Апталық белгі</span><strong>${Math.round(done.length / 7 * 100)}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${Math.round(done.length / 7 * 100)}%"></div></div></div></section>
      <aside><div class="panel plan-settings"><h3>Күніне қанша уақыт?</h3><p>Мақсатыңа, күн тәртібіңе сай таңда. Қысқа әрі тұрақты сабақ та пайдалы.</p><label class="setting-label" for="minutes-range"><span>Оқу уақыты</span><strong id="minutes-value">${state.minutes} минут</strong></label><input id="minutes-range" type="range" min="15" max="120" step="15" value="${state.minutes}"/><div class="range-hint"><span>15 мин</span><span>120 мин</span></div><div class="plan-tip"><b>✳</b><span>Тақырыпты түсінген соң 5–10 тест сұрағымен бекітіп көр.</span></div></div><div class="panel plan-settings" style="margin-top:12px"><h3>Дайындық мақсаты</h3><p>Алдымен барлық бөлімді шолып, белгісіз жерлерді анықта. Қиын тақырыпқа қайта оралу — қалыпты оқу бөлігі.</p><button class="btn btn-primary" style="width:100%" data-view="subjects">Тақырыптарды қарау <span class="arrow">→</span></button></div></aside></div>`;
}

function renderVideos() {
  const visible = videoFilter === 'all' ? videoLessons : videoLessons.filter((video) => video.subject === videoFilter);
  const active = videoLessons.find((video) => video.id === activeVideoId);
  return `<div class="page-heading"><div><p class="eyebrow"><i class="eyebrow-dot"></i>ҚАЗАҚША ВИДЕОСАБАҚТАР</p><h1>Көр, түсін, бір сұрақпен бекіт.</h1><p class="subheading">ҰБТ пәндеріне арналған сабақтар топтамасы. Видеоны ашып көрген соң, негізгі ойды бір сөйлеммен жазып қоюды ұсынамыз.</p></div><a class="btn btn-light heading-action" href="https://www.youtube.com/results?search_query=%D2%B0%D0%91%D0%A2+%D2%9B%D0%B0%D0%B7%D0%B0%D2%9B%D1%88%D0%B0+%D0%B2%D0%B8%D0%B4%D0%B5%D0%BE%D1%81%D0%B0%D0%B1%D0%B0%D2%9B" target="_blank" rel="noreferrer">YouTube-та іздеу ↗</a></div>
    <div class="video-filters"><button class="subject-tab ${videoFilter === 'all' ? 'active reading-tab' : ''}" data-action="video-filter" data-filter="all">Барлық пән</button>${SUBJECT_ORDER.map((id) => `<button class="subject-tab ${videoFilter === id ? `active ${subjects[id].tone}-tab` : ''}" data-action="video-filter" data-filter="${id}">${subjects[id].name}</button>`).join('')}</div>
    ${active ? `<section class="video-player panel"><div class="video-frame"><iframe src="https://www.youtube-nocookie.com/embed/${active.videoId}?rel=0" title="${esc(active.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><div class="video-player-info"><div><span class="video-subject-tag">${subjects[active.subject].name} · ${active.year}</span><h2>${active.title}</h2><p>${active.description}</p></div><button class="btn btn-quiet" data-action="video-watched" data-id="${active.id}">${state.watchedVideos.includes(active.id) ? 'Қаралды ✓' : 'Көріп болдым ✓'}</button></div></section>` : `<div class="video-callout"><span>▶</span><div><strong>Бүгін бір видео жеткілікті.</strong><small>Оны көрген соң, бір мысалды өзің шешіп көр. Оқу барысыңда видео көргенің де белгіленеді.</small></div></div>`}
    <div class="video-grid">${visible.map((video) => `<article class="video-card panel"><button class="video-thumb" data-action="play-video" data-id="${video.id}" aria-label="${esc(video.title)} видеосын ашу"><img src="https://i.ytimg.com/vi/${video.videoId}/hqdefault.jpg" alt="" loading="lazy"><span class="play-button">▶</span>${state.watchedVideos.includes(video.id) ? '<span class="watched-pill">✓ Қаралды</span>' : ''}</button><div class="video-card-copy"><span class="video-subject-tag">${subjects[video.subject].name} · ${video.year}</span><h3>${video.title}</h3><p>${video.description}</p><div class="video-card-foot"><span>${video.channel}</span><button class="text-button" data-action="play-video" data-id="${video.id}">Көру →</button></div></div></article>`).join('')}</div>
    <p class="source-note">Видеолар YouTube платформасындағы ашық сабақтарға сілтейді. Арна мен видеоның қолжетімділігі сыртқы платформаға байланысты. ҰТО спецификациясын негізгі бағдар ретінде қолдан.</p>`;
}

function renderProgress() {
  const total = totalTopicCount();
  const completed = state.doneTopics.filter((id) => SUBJECT_ORDER.some((subjectId) => subjects[subjectId].topics.some((topic) => topic.id === id))).length;
  const coverage = Math.round(completed / total * 100);
  const recent = (state.mockRuns || []).slice(-6).reverse();
  const avg = recent.length ? Math.round(recent.reduce((sum, run) => sum + run.score / run.total, 0) / recent.length * 100) : null;
  const activeDays = (state.studyDays || []).slice(-7).length;
  const milestones = [
    { icon: '✳', title: 'Алғашқы тақырып', detail: 'Бір бөлімді аяқта', unlocked: completed > 0 },
    { icon: '✓', title: 'Алғашқы пробник', detail: 'Бір сынақ тапсыр', unlocked: recent.length > 0 },
    { icon: '7', title: 'Тұрақты ырғақ', detail: '7 күнде 5 күн оқу', unlocked: activeDays >= 5 },
    { icon: '★', title: 'Он тақырып', detail: '10 тақырыпты белгіле', unlocked: completed >= 10 }
  ];
  const weak = Object.entries(state.mistakes || {}).sort((a, b) => b[1].count - a[1].count).slice(0, 4);
  const best = recent.length ? Math.max(...recent.map((run) => Math.round(run.score / run.total * 100))) : 0;
  return `<div class="page-heading"><div><p class="eyebrow"><i class="eyebrow-dot"></i>ЖЕКЕ НӘТИЖЕ</p><h1>Прогресің — өз еңбегіңнің ізі.</h1><p class="subheading">Меңгерген тақырыптарың, жаттығулар және оқу күндері осы құрылғыда сақталады. Нәтижені келесі қайталауды таңдауға пайдалан.</p></div><button class="btn btn-primary heading-action" data-view="quiz">Пробник тапсыру <span class="arrow">→</span></button></div>
    <div class="progress-overview"><article class="panel progress-main-card"><div class="progress-main-top"><div><span class="small-label">ТҮСІНІКТІ БОЛҒАН ТАҚЫРЫПТАР</span><div class="progress-big-number">${completed}<span> / ${total}</span></div><p>Бес пәннің тақырып картасынан белгіленген бөлімдер</p></div><div class="progress-donut" style="--progress:${coverage}%"><div><strong>${coverage}%</strong><span>тақырып</span></div></div></div><div class="progress-track"><div class="progress-fill" style="width:${coverage}%"></div></div><div class="progress-bottom-note"><span>${coverage === 0 ? 'Бірінші тақырыпты аяқтағанда, бұл көрсеткіш өзгере бастайды.' : 'Әр белгіленген тақырып — алға жасалған нақты қадам.'}</span><button class="inline-link" data-view="subjects">Тақырыптарға өту →</button></div></article><div class="progress-stat-stack"><article class="panel progress-stat-card"><span class="progress-stat-icon">✳</span><div><strong>${calcStreak()}</strong><span>күндік оқу қатары</span></div></article><article class="panel progress-stat-card"><span class="progress-stat-icon">✓</span><div><strong>${state.quizRuns || 0}</strong><span>аяқталған жаттығу</span></div></article><article class="panel progress-stat-card"><span class="progress-stat-icon">${avg === null ? '—' : '↗'}</span><div><strong>${avg === null ? '—' : `${avg}%`}</strong><span>${avg === null ? 'алғашқы жаттығуды тапсыр' : `соңғы орташа нәтиже · үздігі ${best}%`}</span></div></article></div></div>
    <div class="progress-columns"><section class="panel progress-subject-panel"><div class="section-heading"><div><h2>Пәндер бойынша ілгерілеу</h2><p>Тақырыптарды белгілеу көрсеткіші</p></div></div>${SUBJECT_ORDER.map((id) => { const s = subjects[id]; const count = topicCount(id); const pct = Math.round(count / s.topics.length * 100); return `<div class="subject-progress-row"><span class="subject-progress-icon ${s.tone}">${s.symbol}</span><div class="subject-progress-content"><div><strong>${s.name}</strong><span>${count}/${s.topics.length} · ${pct}%</span></div><div class="progress-track"><div class="progress-fill ${s.tone}-fill" style="width:${pct}%"></div></div></div></div>`; }).join('')}</section><section class="panel milestones-panel"><div class="section-heading"><div><h2>Кішкентай белестер</h2><p>Өзіңе белгі қойып отыр</p></div></div><div class="milestone-list">${milestones.map((item) => `<div class="milestone ${item.unlocked ? 'unlocked' : ''}"><span>${item.unlocked ? item.icon : '·'}</span><div><strong>${item.title}</strong><small>${item.detail}</small></div>${item.unlocked ? '<b>✓</b>' : ''}</div>`).join('')}</div></section></div>
    <div class="progress-columns lower-progress"><section class="panel progress-subject-panel"><div class="section-heading"><div><h2>Қай тақырыпқа оралған дұрыс?</h2><p>Қате жауаптардан жиі шыққан тақырыптар</p></div></div>${weak.length ? `<div class="weak-list">${weak.map(([key, item]) => { const [subjectId, ...name] = key.split('|'); return `<div class="weak-row"><span class="weak-subject">${subjects[subjectId]?.name || 'Пән'}</span><strong>${name.join('|')}</strong><span>${item.count} қате</span><button class="text-button" data-action="open-subject" data-subject="${subjectId}">Қайталау →</button></div>`; }).join('')}</div>` : '<div class="empty-state"><span>✳</span><p>Пробник тапсырған соң, қай сұрақтар қиын болғанын осында жинаймыз.</p><button class="btn btn-quiet" data-view="quiz">Алғашқы жаттығу</button></div>'}</section><section class="panel progress-subject-panel"><div class="section-heading"><div><h2>Соңғы жаттығулар</h2><p>Нәтиже жеке оқу жаттығуларына қатысты</p></div><button class="inline-link" data-view="quiz">Барлық тест →</button></div>${recent.length ? `<div class="recent-runs">${recent.map((run) => `<div class="recent-run"><span class="run-icon">✓</span><div><strong>${run.title}</strong><small>${run.date} · ${run.duration} мин</small></div><b>${run.score}/${run.total}</b></div>`).join('')}</div>` : '<div class="empty-state"><span>◷</span><p>Алғашқы қысқа жаттығуыңды орындағанда нәтиже осында көрінеді.</p><button class="btn btn-quiet" data-view="quiz">Тестке өту</button></div>'}</section></div>`;
}

function shuffle(items) {
  const list = [...items];
  for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; }
  return list;
}
function buildQuizQuestions(mode, subjectId) {
  if (mode === 'mixed') {
    const quotas = { mathlit: 2, reading: 2, history: 4, bio: 8, chem: 8 };
    return shuffle(Object.entries(quotas).flatMap(([id, count]) => shuffle(quizBanks[id]).slice(0, count).map((q) => ({ ...q, subject: id }))));
  }
  return shuffle(quizBanks[subjectId].map((q) => ({ ...q, subject: subjectId })));
}
function renderQuiz() {
  const chosen = subjects[quizChoice];
  const subjectOptions = SUBJECT_ORDER.map((id) => {
    const s = subjects[id];
    return `<button class="quiz-subject-option ${s.tone} ${quizChoice === id && quizMode === 'subject' ? 'selected' : ''}" data-action="quiz-subject" data-subject="${id}"><span class="quiz-choice-mark">${s.symbol}</span><span><strong>${s.name}</strong><small>${quizBanks[id].length} оқу сұрағы · ${s.questionCount} ресми тапсырма</small></span></button>`;
  }).join('');
  const startCard = `<div class="quiz-start"><p class="eyebrow"><i class="eyebrow-dot"></i>ТАПСЫРМА ЖӘНЕ КЕРІ БАЙЛАНЫС</p><h2>Дайындығыңды әртүрлі форматта тексер.</h2><p>Пәндік жаттығуда сұрақтар мен түсіндірмелер беріледі. Аралас диагностика бес пәннен шағын сынақ құрайды. Нәтиже осы сайттағы оқу жаттығуына арналған; толық ҰБТ нұсқасын ҰТО платформасында тапсыр.</p><div class="quiz-mode-switch"><button class="mode-option ${quizMode === 'subject' ? 'active' : ''}" data-action="quiz-mode" data-mode="subject"><strong>Бір пән</strong><small>тақырыптық қайталау</small></button><button class="mode-option ${quizMode === 'mixed' ? 'active' : ''}" data-action="quiz-mode" data-mode="mixed"><strong>Аралас диагностика</strong><small>5 пән · 24 сұрақ</small></button></div>${quizMode === 'subject' ? `<div class="quiz-options">${subjectOptions}</div><p class="selected-test-note">${chosen.required ? 'Міндетті пән' : 'Бейіндік пән'}: ${quizBanks[quizChoice].length} сұрақтық оқу жинағы. Әр жауаптың түсіндірмесін көріп, нәтижені прогресс бетінде сақта.</p>` : `<div class="mixed-preview"><span>2</span> математикалық сауаттылық <span>· 2</span> оқу сауаттылығы <span>· 4</span> Қазақстан тарихы <span>· 8</span> биология <span>· 8</span> химия</div>`}<button class="btn btn-primary" data-action="start-quiz">${quizMode === 'mixed' ? '24 сұрақтық диагностика' : `${chosen.name} жаттығуын бастау`} <span class="arrow">→</span></button></div>`;
  let quizContent = startCard;
  if (quizRun && ((quizRun.mode === 'mixed' && quizMode === 'mixed') || (quizRun.mode === 'subject' && quizRun.subject === quizChoice && quizMode === 'subject'))) {
    quizContent = quizRun.finished ? renderQuizResult() : renderQuizQuestion();
  }
  return `<div class="page-heading"><div><p class="eyebrow"><i class="eyebrow-dot"></i>ТӘЖІРИБЕ ЖӘНЕ КЕРІ БАЙЛАНЫС</p><h1>Тексер, талда, тағы да байқап көр.</h1><p class="subheading">Қате — қай тақырыпқа қайта оралу керегін көрсететін белгі. Нәтижелерің оқу барысына сақталады.</p></div></div><div class="quiz-layout"><section class="panel quiz-card">${quizContent}</section><aside class="quiz-side"><div class="panel quiz-info-card"><h3>ҰБТ-ның ресми құрылымы</h3><p>3 міндетті пән және 2 бейіндік пән: барлығы 120 тапсырма, ең көбі 140 балл, 240 минут.</p><div class="format-list"><div class="format-row"><span>Қазақстан тарихы</span><strong>20 · 20 балл</strong></div><div class="format-row"><span>Оқу сауаттылығы</span><strong>10 · 10 балл</strong></div><div class="format-row"><span>Математикалық сауаттылық</span><strong>10 · 10 балл</strong></div><div class="format-row"><span>Екі бейіндік пән</span><strong>әрқайсысы 40 · 50 балл</strong></div></div></div><div class="panel quiz-info-card"><h3>Толық ҰБТ байқауы</h3><p>ҰТО сайтында тегін толық форматтағы байқау тестін тапсыруға болады. Жеке кабинет қажет болуы мүмкін.</p><p style="margin-top:12px"><a href="${SPEC_URLS.freeTest}" target="_blank" rel="noreferrer">ҰТО байқау тестіне өту ↗</a></p><p class="source-note">Мұндағы пәндік және аралас жаттығулар түсіндірмесі бар шағын оқу тесттері; олар толық ресми нұсқаны алмастырмайды.</p></div></aside></div>`;
}

function renderQuizQuestion() {
  const q = quizRun.questions[quizRun.step];
  const selected = quizRun.answers[quizRun.step] || [];
  const checked = quizRun.checked;
  const answerMarkup = q.options.map((option, i) => {
    const right = q.correct.includes(i); const chosen = selected.includes(i);
    const className = checked ? (right ? 'correct-answer' : (chosen ? 'wrong-answer' : '')) : '';
    return `<label class="answer-option ${className}"><input type="${q.type === 'multi' ? 'checkbox' : 'radio'}" name="quiz-answer" value="${i}" ${chosen ? 'checked' : ''} ${checked ? 'disabled' : ''}/><span>${option}</span></label>`;
  }).join('');
  const progress = Math.round((quizRun.step + (checked ? 1 : 0)) / quizRun.questions.length * 100);
  const exact = selected.length === q.correct.length && selected.every((x) => q.correct.includes(x));
  return `<div class="quiz-question-top"><span class="quiz-progress-label">${quizRun.title} · ${quizRun.step + 1}/${quizRun.questions.length} сұрақ</span><span class="quiz-timer"><i></i>Уақыт <b id="quiz-elapsed">${formatElapsed(Date.now() - quizRun.startedAt)}</b></span></div><div class="quiz-progress-track"><span style="width:${progress}%"></span></div><span class="quiz-tag">${subjects[q.subject].name} · ${q.type === 'multi' ? 'БІР НЕМЕСЕ БІРНЕШЕ ЖАУАП' : q.context ? 'КОНТЕКСТ НЕГІЗІНДЕ' : 'БІР ДҰРЫС ЖАУАП'} · ${q.topic}</span>${q.context ? `<div class="quiz-context">${q.context}</div>` : ''}<h2 class="quiz-question">${q.question}</h2><div class="answer-list" id="answer-list">${answerMarkup}</div><div class="quiz-explanation ${checked ? 'show' : ''}"><strong>${checked ? (exact ? 'Дұрыс жауап.' : 'Қайталап көр.') : ''}</strong> ${checked ? q.explanation : ''}</div><div class="quiz-controls"><span class="quiz-score">${checked ? (exact ? 'Дұрыс · 1 оқу ұпайы' : 'Жауап түсіндірмесі көрсетілді') : (q.type === 'multi' ? 'Барлық дұрыс жауапты таңда.' : 'Бір жауапты таңда.')}</span>${checked ? `<button class="btn btn-primary" data-action="quiz-next">${quizRun.step === quizRun.questions.length - 1 ? 'Нәтижені көру' : 'Келесі сұрақ'} <span class="arrow">→</span></button>` : `<button class="btn btn-primary" data-action="quiz-check" ${selected.length ? '' : 'disabled'}>Жауапты тексеру <span class="arrow">→</span></button>`}</div>`;
}

function renderQuizResult() {
  const score = quizRun.score; const total = quizRun.questions.length; const percent = Math.round(score / total * 100);
  const message = percent >= 80 ? 'Өте жақсы қарқын. Енді әлсіз тақырыптарды қарап, келесі пәнді таңдай аласың.' : percent >= 50 ? 'Жақсы жұмыс. Қате сұрақтардың түсіндірмесін қайталап, тағы бір шағын жаттығу жасап көр.' : 'Бұл — бастапқы өлшем. Қателерден бір тақырыпты таңдап, соған қайта орал.';
  return `<div class="quiz-result"><div class="result-ring">${score}/${total}</div><p class="eyebrow"><i class="eyebrow-dot"></i>ЖАТТЫҒУ АЯҚТАЛДЫ · ${percent}%</p><h2>${quizRun.title} · нәтижең</h2><p>${message} Бұл оқу жаттығуының ұпайы, ресми ҰБТ балы емес. Қате тақырыптар прогресс бөліміне қосылды.</p><div style="display:flex;gap:9px;flex-wrap:wrap;justify-content:center"><button class="btn btn-primary" data-action="start-quiz">Қайта тапсыру <span class="arrow">↻</span></button><button class="btn btn-light" data-view="progress">Прогресті талдау</button></div></div>`;
}

function finishQuiz() {
  if (!quizRun || quizRun.recorded) return;
  quizRun.finished = true; quizRun.recorded = true;
  const duration = Math.max(1, Math.round((Date.now() - quizRun.startedAt) / 60000));
  quizRun.questions.forEach((q, i) => {
    const selected = quizRun.answers[i] || [];
    const correct = selected.length === q.correct.length && selected.every((answer) => q.correct.includes(answer));
    if (!correct) {
      const key = `${q.subject}|${q.topic}`;
      state.mistakes[key] = { count: (state.mistakes[key]?.count || 0) + 1 };
    }
  });
  state.quizRuns = (state.quizRuns || 0) + 1;
  state.bestQuiz[quizRun.mode === 'mixed' ? 'mixed' : quizRun.subject] = Math.max(state.bestQuiz[quizRun.mode === 'mixed' ? 'mixed' : quizRun.subject] || 0, quizRun.score);
  state.mockRuns = [...(state.mockRuns || []), { date: new Date().toLocaleDateString('kk-KZ'), title: quizRun.title, subject: quizRun.subject, score: quizRun.score, total: quizRun.questions.length, duration }].slice(-40);
  touchStudyday(); save(); render();
}

function filteredFlashcards() { return flashFilter === 'all' ? flashcards : flashcards.filter((c) => c.subject === flashFilter); }
function renderReview() {
  const cards = filteredFlashcards();
  if (flashIndex >= cards.length) flashIndex = 0;
  const card = cards[flashIndex];
  const seenCount = state.seenCards.filter((id) => cards.some((c) => c.id === id)).length;
  const isKnown = state.seenCards.includes(card.id);
  return `<div class="page-heading"><div><p class="eyebrow"><i class="eyebrow-dot"></i>БЕЛСЕНДІ ҚАЙТАЛАУ</p><h1>Есте сақтауды жеңілдет.</h1><p class="subheading">Карточканы аударып анықтамасын көр. Күнделікті қысқа қайталау терминдерді есте ұстауға көмектеседі.</p></div></div><div class="review-layout"><section class="panel"><div class="flashcard-wrap"><article class="flashcard" id="flashcard" data-action="flip-card"><div class="flash-face front"><span class="flash-category">${card.category}</span><strong class="flash-term">${card.term}</strong><span class="flash-hint">Анықтамасын көру үшін түрт</span></div><div class="flash-face back"><span class="flash-category">ТҮСІНІКТЕМЕ</span><p class="flash-definition">${card.definition}</p><span class="flash-hint">Келесі карточкаға өтуге болады</span></div></article></div><div class="flash-controls"><button class="flash-button" data-action="flash-prev" aria-label="Алдыңғы карточка">←</button><span class="flash-count">${flashIndex + 1} / ${cards.length}</span><button class="flash-button" data-action="flash-next" aria-label="Келесі карточка">→</button><button class="flash-known ${isKnown ? 'done' : ''}" data-action="flash-known">${isKnown ? 'Қайталадым ✓' : 'Қайталадым'}</button></div></section><aside class="panel review-side"><h3>Карточкалар жинағы</h3><p>Анықтаманы оқығанда таныс болғанын белгіле. Жинақ алға жылжуыңды осы құрылғыда сақтайды.</p><div class="review-stats"><div class="review-stat"><strong>${seenCount}</strong><span>осы жинақта қайталадым</span></div><div class="review-stat"><strong>${cards.length}</strong><span>карточка</span></div></div><div class="review-subjects">${SUBJECT_ORDER.map((id) => `<button class="review-filter ${flashFilter === id ? 'active' : ''}" data-action="flash-filter" data-filter="${id}"><span>${subjects[id].name}</span><span>${flashcards.filter((c) => c.subject === id).length}</span></button>`).join('')}<button class="review-filter ${flashFilter === 'all' ? 'active' : ''}" data-action="flash-filter" data-filter="all"><span>Барлық пән</span><span>${flashcards.length}</span></button></div></aside></div>`;
}

function showFormatModal() {
  modalBody.innerHTML = `<h2 class="modal-title" id="modal-title">ҰБТ форматы: қысқаша</h2><p class="modal-lead">ҰТО-ның 2026 жылдан қолданылатын материалдары бойынша. Биология мен химия — мүмкін бейіндік пәндер комбинациясының бірі.</p><div class="format-summary"><div class="format-stat"><strong>120</strong><span>барлық тапсырма</span></div><div class="format-stat"><strong>140</strong><span>ең жоғары балл</span></div><div class="format-stat"><strong>240 мин</strong><span>тестілеу уақыты</span></div></div><h3 class="modal-subhead">Тест құрамы</h3><ul class="modal-list"><li>3 міндетті пән: Қазақстан тарихы — 20 тапсырма, оқу сауаттылығы — 10, математикалық сауаттылық — 10.</li><li>2 бейіндік пән таңдалған білім беру бағдарламалары тобына сәйкес алынады. Әр бейіндік пәнде — 40 тапсырма және ең көбі 50 балл.</li><li>Бейіндік тапсырмаларда бір дұрыс жауап, контекст, бірнеше жауап және сәйкестікті анықтау форматтары бар.</li><li>Бұл сайттағы жаттығулар — түсіндірмесі бар оқу тесттері. Толық 120 тапсырмалық байқауды ҰТО платформасында тапсыр.</li></ul><h3 class="modal-subhead">Ресми сілтемелер</h3><div class="source-links"><a href="${SPEC_URLS.format}" target="_blank" rel="noreferrer">ҰТО · тестілеу форматы <small>Ресми бет ↗</small></a><a href="${SPEC_URLS.prep}" target="_blank" rel="noreferrer">ҰТО · тестке дайындық <small>Спецификациялар және тесттер ↗</small></a><a href="${SPEC_URLS.freeTest}" target="_blank" rel="noreferrer">ҰТО · тегін байқау тесті <small>prob-ent ↗</small></a></div>`;
  openModal();
}
function showSourcesModal() {
  modalBody.innerHTML = `<h2 class="modal-title" id="modal-title">Ресми дереккөздер</h2><p class="modal-lead">Сайттағы пән тақырыптары мен формат туралы мәліметтер Ұлттық тестілеу орталығының қазақша материалдарына сүйенеді.</p><div class="source-links"><a href="${SPEC_URLS.history}" target="_blank" rel="noreferrer">Қазақстан тарихы · ҰБТ спецификациясы <small>2026 жылдан бастап ↗</small></a><a href="${SPEC_URLS.reading}" target="_blank" rel="noreferrer">Оқу сауаттылығы · ҰБТ спецификациясы <small>2026 жылдан бастап ↗</small></a><a href="${SPEC_URLS.mathlit}" target="_blank" rel="noreferrer">Математикалық сауаттылық · ҰБТ спецификациясы <small>2026 жылдан бастап ↗</small></a><a href="${SPEC_URLS.biology}" target="_blank" rel="noreferrer">Биология · ҰБТ спецификациясы <small>2026 жылдан бастап ↗</small></a><a href="${SPEC_URLS.chemistry}" target="_blank" rel="noreferrer">Химия · ҰБТ спецификациясы <small>2026 жылдан бастап ↗</small></a><a href="${SPEC_URLS.format}" target="_blank" rel="noreferrer">ҰБТ форматы <small>Ұлттық тестілеу орталығы ↗</small></a><a href="${SPEC_URLS.prep}" target="_blank" rel="noreferrer">Дайындық материалдары <small>ҰТО үлгі тесттері ↗</small></a><a href="${SPEC_URLS.freeTest}" target="_blank" rel="noreferrer">Тегін байқау тесті <small>ҰТО платформасы ↗</small></a></div><p class="source-note" style="margin-top:15px">Тақырып астындағы қысқаша оқу бағыттары — дайындыққа арналған түсіндірме. Толық мазмұн мен ең соңғы өзгерістер үшін ресми спецификацияны басшылыққа ал.</p>`;
  openModal();
}
function openModal() { modal.hidden = false; overlay.hidden = false; document.getElementById('modal-close').focus(); }
function closeModal() { modal.hidden = true; overlay.hidden = true; }

function currentQuizSelection() { return [...document.querySelectorAll('#answer-list input:checked')].map((input) => Number(input.value)); }
function updateQuizSelection() {
  if (!quizRun) return;
  quizRun.answers[quizRun.step] = currentQuizSelection();
  const btn = main.querySelector('[data-action="quiz-check"]');
  if (btn) btn.disabled = quizRun.answers[quizRun.step].length === 0;
}

document.addEventListener('click', (event) => {
  const viewButton = event.target.closest('[data-view]');
  if (viewButton) { event.preventDefault(); setView(viewButton.dataset.view); return; }
  const actionButton = event.target.closest('[data-action]');
  if (!actionButton) return;
  const { action, id, subject, index, filter } = actionButton.dataset;
  if (action === 'continue') {
    activeSubject = subject || 'bio'; setView('subjects');
    const next = subjects[activeSubject].topics.find((t) => !state.doneTopics.includes(t.id));
    if (next) { selectedTopicId = next.id; expandedSections[activeSubject].add(next.sectionIndex); render(); }
  }
  if (action === 'daily-task') {
    const key = localDateKey(); const tasks = new Set(state.dailyTasks[key] || []);
    const wasDone = tasks.has(id);
    wasDone ? tasks.delete(id) : tasks.add(id);
    state.dailyTasks[key] = [...tasks]; if (!wasDone) touchStudyday(); save(); render();
  }
  if (action === 'open-topic') {
    activeSubject = subject || 'bio'; selectedTopicId = id; expandedSections[activeSubject].add(subjects[activeSubject].topics.find((t) => t.id === id).sectionIndex); subjectSearch = ''; setView('subjects'); render();
  }
  if (action === 'open-subject') { activeSubject = subject; selectedTopicId = null; subjectSearch = ''; expandedSections[subject].add(0); setView('subjects'); }
  if (action === 'choose-subject') { activeSubject = subject; subjectSearch = ''; selectedTopicId = null; render(); }
  if (action === 'toggle-section') {
    const n = Number(index); const set = expandedSections[activeSubject]; set.has(n) ? set.delete(n) : set.add(n); render();
  }
  if (action === 'select-topic') { selectedTopicId = id; render(); }
  if (action === 'toggle-topic') {
    const done = new Set(state.doneTopics);
    if (done.has(id)) { done.delete(id); showToast('Тақырып белгісі алынды. Қайта оқи аласың.'); }
    else { done.add(id); touchStudyday(); showToast('Тақырып оқу барысына қосылды.'); }
    state.doneTopics = [...done]; save(); render();
  }
  if (action === 'plan-day') {
    const key = weekKey(); const days = new Set(state.planDone[key] || []); const n = Number(index);
    days.has(n) ? days.delete(n) : days.add(n);
    state.planDone[key] = [...days]; if (days.has(n)) touchStudyday(); save(); render();
  }
  if (action === 'show-format') showFormatModal();
  if (action === 'video-filter') { videoFilter = filter; activeVideoId = null; render(); }
  if (action === 'play-video') { activeVideoId = id; render(); main.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
  if (action === 'video-watched') {
    const alreadyWatched = state.watchedVideos.includes(id);
    if (!alreadyWatched) state.watchedVideos.push(id);
    if (!alreadyWatched) touchStudyday(); save(); render(); showToast('Видеосабақ оқу барысына қосылды.');
  }
  if (action === 'quiz-subject') { quizChoice = subject; quizMode = 'subject'; quizRun = null; render(); }
  if (action === 'quiz-mode') { quizMode = actionButton.dataset.mode; quizRun = null; render(); }
  if (action === 'start-quiz') {
    const questions = buildQuizQuestions(quizMode, quizChoice);
    quizRun = { mode: quizMode, subject: quizMode === 'mixed' ? 'mixed' : quizChoice, title: quizMode === 'mixed' ? '5 пән · аралас диагностика' : subjects[quizChoice].name, questions, answers: Array(questions.length).fill(null), step: 0, checked: false, finished: false, score: 0, startedAt: Date.now() };
    render();
  }
  if (action === 'quiz-check' && quizRun) {
    const q = quizRun.questions[quizRun.step];
    const selected = quizRun.answers[quizRun.step] || [];
    quizRun.checked = true;
    const exact = selected.length === q.correct.length && selected.every((x) => q.correct.includes(x));
    if (exact) quizRun.score++;
    render();
  }
  if (action === 'quiz-next' && quizRun) {
    if (quizRun.step < quizRun.questions.length - 1) { quizRun.step++; quizRun.checked = false; render(); }
    else finishQuiz();
  }
  if (action === 'flip-card') actionButton.classList.toggle('flipped');
  if (action === 'flash-prev' || action === 'flash-next') {
    const cards = filteredFlashcards(); flashIndex = (flashIndex + (action === 'flash-next' ? 1 : cards.length - 1)) % cards.length; render();
  }
  if (action === 'flash-known') {
    const card = filteredFlashcards()[flashIndex];
    if (!state.seenCards.includes(card.id)) state.seenCards.push(card.id);
    touchStudyday(); save(); flashIndex = (flashIndex + 1) % filteredFlashcards().length; render(); showToast('Қайталау барысы сақталды.');
  }
  if (action === 'flash-filter') { flashFilter = filter; flashIndex = 0; render(); }
});

document.addEventListener('change', (event) => {
  if (event.target.matches('#answer-list input')) updateQuizSelection();
  if (event.target.matches('#minutes-range')) {
    state.minutes = Number(event.target.value); save();
    document.getElementById('minutes-value').textContent = `${state.minutes} минут`;
    document.querySelectorAll('.plan-minute').forEach((el) => { el.textContent = `${state.minutes} мин`; });
  }
});
document.addEventListener('input', (event) => {
  if (event.target.matches('#topic-search')) {
    subjectSearch = event.target.value;
    const cursor = event.target.selectionStart;
    render();
    const next = document.getElementById('topic-search'); next.focus(); next.setSelectionRange(cursor, cursor);
  }
});

document.getElementById('mobile-menu').addEventListener('click', () => {
  document.getElementById('sidebar').classList.toggle('open'); overlay.hidden = !document.getElementById('sidebar').classList.contains('open');
});
document.getElementById('help-button').addEventListener('click', showFormatModal);
document.getElementById('sources-button').addEventListener('click', showSourcesModal);
document.getElementById('modal-close').addEventListener('click', closeModal);
overlay.addEventListener('click', () => { closeModal(); document.getElementById('sidebar').classList.remove('open'); });
document.addEventListener('keydown', (event) => { if (event.key === 'Escape') { closeModal(); document.getElementById('sidebar').classList.remove('open'); overlay.hidden = true; } });

render();
